import { DECKS, type DeckId } from './deck'

/**
 * Which card comes next.
 *
 * Two rules, both about trust:
 *
 *  1. The daily card is derived from the DATE, not from a random number. Both
 *     phones therefore show the same card on the same day without syncing
 *     anything, which is the whole point of "kartu hari ini" for a couple who
 *     are apart.
 *  2. Drawing never repeats a question until the deck has been exhausted. A
 *     shuffle that can hand you the same card twice in five draws reads as
 *     broken, however random it technically is.
 */

export interface DrawState {
  /** Indices already drawn, per deck. */
  seen: Partial<Record<DeckId, number[]>>
}

/** Stable per-day, per-deck index. */
export function dailyIndex(deck: DeckId, date: Date = new Date()): number {
  const d = DECKS.find((x) => x.id === deck)
  if (!d || d.questions.length === 0) return 0
  const key = `${deck}-${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`
  let h = 2166136261
  for (let i = 0; i < key.length; i++) {
    h ^= key.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return (h >>> 0) % d.questions.length
}

/**
 * Next unseen index, or a fresh cycle once every card has been drawn.
 * Returns the index plus whether the deck just wrapped, so the screen can say
 * so rather than silently starting again.
 */
export function nextIndex(
  deck: DeckId,
  state: DrawState,
  random: () => number = Math.random,
): { index: number; wrapped: boolean } {
  const d = DECKS.find((x) => x.id === deck)
  const total = d?.questions.length ?? 0
  if (total === 0) return { index: 0, wrapped: false }

  const seen = state.seen[deck] ?? []
  const remaining: number[] = []
  for (let i = 0; i < total; i++) if (!seen.includes(i)) remaining.push(i)

  if (remaining.length === 0) {
    return { index: Math.floor(random() * total), wrapped: true }
  }
  return { index: remaining[Math.floor(random() * remaining.length)]!, wrapped: false }
}

export function markSeen(state: DrawState, deck: DeckId, index: number): DrawState {
  const seen = state.seen[deck] ?? []
  if (seen.includes(index)) return state
  return { seen: { ...state.seen, [deck]: [...seen, index] } }
}

/** Cards left in a deck. */
export function remainingCount(deck: DeckId, state: DrawState): number {
  const total = DECKS.find((x) => x.id === deck)?.questions.length ?? 0
  return Math.max(0, total - (state.seen[deck]?.length ?? 0))
}

export function resetDeck(state: DrawState, deck: DeckId): DrawState {
  const next = { ...state.seen }
  delete next[deck]
  return { seen: next }
}
