/**
 * The question bank.
 *
 * Written for Indonesian couples specifically, not translated from an English
 * deck. The difference shows up in what the questions assume: that parents have
 * a real say, that money moves toward the extended family, that "kapan nikah?"
 * and "kapan punya anak?" arrive at every kondangan, that mudik and THR are
 * budget events, and that a lot of the hardest things are the ones nobody says
 * out loud at the dinner table.
 *
 * Grounded in what Indonesian family research keeps reporting as the recurring
 * flashpoints — campur tangan mertua in decisions, household economics and
 * parenting, and a communal culture where the line between a couple's private
 * life and their parents' role is thin.
 *
 * ON THE NUMBER OF QUESTIONS. The brief asked for thousands per category and
 * also — rightly — said not to force it and end up with irrelevant filler.
 * Those two pull against each other, and relevance wins: a deck padded to
 * 7,000 with reworded duplicates is worse than a tight one, because the third
 * time you draw "apa warna favoritmu?" you stop trusting the deck. So this is
 * a curated bank, every line written to be worth answering, and `deck.test.ts`
 * enforces that no two questions are near-duplicates.
 *
 * The bank is designed to grow: add lines to these arrays and everything else —
 * the daily draw, the art, the counts on screen — follows automatically.
 */

import type { MessageKey } from '@/i18n'

export type DeckId =
  | 'dalam' // deep
  | 'receh' // funny
  | 'genit' // flirty
  | 'seru' // fun
  | 'berat' // heavy
  | 'manis' // extra sweet
  | 'acak' // random

export interface Deck {
  id: DeckId
  /** Message key for the human name — typed, so a typo fails the build. */
  name: MessageKey
  desc: MessageKey
  questions: string[]
}

