export const DECK_BY_ID = new Map(DECKS.map((d) => [d.id, d]))

/** Every question in the bank, flattened, with its deck. */
export function allCards(): { deck: DeckId; index: number; text: string }[] {
  return DECKS.flatMap((d) => d.questions.map((text, index) => ({ deck: d.id, index, text })))
}

export function totalQuestions(): number {
  return DECKS.reduce((n, d) => n + d.questions.length, 0)
}
