import { cardArt } from './design'
import { Motif } from './Motif'
import './cards.css'

/**
 * One card.
 *
 * Composition follows the printed decks this is modelled on: a drawing on top,
 * the question under it, a small flourish to close. Nothing on the card
 * explains the app — a card that describes its own colour system is a card
 * nobody wants to read.
 */
export interface CardFaceProps {
  deck: string
  index: number
  text: string
  /** Quiet label above the drawing, e.g. the deck name. */
  kicker?: string
  compact?: boolean
  className?: string
}

export function CardFace({ deck, index, text, kicker, compact, className }: CardFaceProps) {
  const art = cardArt(deck, index)

  return (
    <article
      className={[
        'cardface',
        `cardface--${art.frame}`,
        compact ? 'cardface--compact' : '',
        className,
      ]
        .filter(Boolean)
        .join(' ')}
      style={{
        background: `linear-gradient(${art.angle}deg, ${art.palette.stops.join(', ')})`,
        color: art.palette.ink,
        ['--card-accent' as string]: art.palette.accent,
      }}
    >
      <div className="cardface__inner">
        {kicker && <span className="cardface__kicker">{kicker}</span>}

        <svg
          className="cardface__motif"
          viewBox="0 0 100 100"
          aria-hidden="true"
          style={{ width: `${art.motifSize}%` }}
        >
          <Motif id={art.motif} tone={art.palette.accent} />
        </svg>

        <p className="cardface__q" style={{ fontSize: `calc(var(--card-q) * ${art.typeScale})` }}>
          {text}
        </p>

        {/* The closing mark. Every reference deck has one; it tells your eye the
            card is finished. */}
        <svg className="cardface__end" viewBox="0 0 24 24" aria-hidden="true">
          <path
            d="M12 20s-7-4.2-7-9a3.9 3.9 0 0 1 7-2.4A3.9 3.9 0 0 1 19 11c0 4.8-7 9-7 9Z"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinejoin="round"
          />
        </svg>
      </div>
    </article>
  )
}
