import { MOTIFS, type MotifId } from './Motif'

/**
 * Card art.
 *
 * Drawing a unique card by hand for every question is not a real option, and one
 * shared template is the "they all look the same" result to avoid. So the art is
 * GENERATED: every card derives a full visual spec — palette, drawing, frame,
 * type scale — from a seed made of its deck and index.
 *
 * Two properties matter and both come from the seed being deterministic:
 *
 *  - The same card always looks the same. Draw "Kapan terakhir kamu nangis?"
 *    today and next month and it is the same card, which is what makes it feel
 *    like a physical deck rather than a random skin each time.
 *  - No storage. Nothing about the art is saved; it is recomputed from the id.
 *
 * The combination space is far larger than the deck will ever hold, so two cards
 * in one sitting never look the same. None of this is ever explained on screen:
 * the user should just feel that the deck is varied.
 */

export interface CardArt {
  palette: Palette
  angle: number
  /** The drawing at the top of the card. */
  motif: MotifId
  /** How large that drawing sits, as a % of card width. */
  motifSize: number
  /** Border/paper treatment. */
  frame: FrameId
  /** Multiplier on the question's font size. */
  typeScale: number
}

export interface Palette {
  id: string
  /** Two gradient stops — kept close together so the card reads as paper. */
  stops: string[]
  /** Ink guaranteed readable on both stops. */
  ink: string
  /** Fills the drawing. */
  accent: string
}

export type FrameId = 'plain' | 'inset' | 'dashed' | 'rounded' | 'tape'

/**
 * Palettes. Soft paper backgrounds with a saturated accent for the drawing —
 * the pairing every printed affirmation deck uses, and the reason the text
 * stays comfortable to read for a whole conversation. Checked against WCAG AA
 * before being written here; `cards.test.ts` re-derives the ratios.
 */
export const PALETTES: Palette[] = [
  { id: 'krem', stops: ['#FFF6EC', '#FFEEDC'], ink: '#4A3520', accent: '#F2A33C' },
  { id: 'blush', stops: ['#FFF0F3', '#FFE3EA'], ink: '#6B2440', accent: '#F1789B' },
  { id: 'sage', stops: ['#F0F7EE', '#E2F0DE'], ink: '#2C4726', accent: '#6FAE5E' },
  { id: 'langit', stops: ['#EEF6FD', '#DFEDFA'], ink: '#1E3E5C', accent: '#4E9BD4' },
  { id: 'lila', stops: ['#F4F0FE', '#E9E2FC'], ink: '#3A2A6B', accent: '#8C74E0' },
  { id: 'mint', stops: ['#ECF9F4', '#DCF2EA'], ink: '#17493C', accent: '#41B394' },
  { id: 'peach', stops: ['#FFF2EC', '#FFE4D8'], ink: '#5E3320', accent: '#F0854F' },
  { id: 'lemon', stops: ['#FFFAE8', '#FFF3CE'], ink: '#544300', accent: '#E0B21C' },
  { id: 'mawar', stops: ['#FDF0F6', '#F8E2EF'], ink: '#5B2149', accent: '#D96BA8' },
  { id: 'kabut', stops: ['#F3F4F8', '#E8EAF1'], ink: '#2E3340', accent: '#7C86A0' },
  { id: 'terakota', stops: ['#FDF1EA', '#F7E2D6'], ink: '#5A2E1C', accent: '#C86A42' },
  { id: 'laut', stops: ['#EDF7F9', '#DCEFF3'], ink: '#173F49', accent: '#3E9CAE' },
]

const FRAMES: FrameId[] = ['plain', 'inset', 'dashed', 'rounded', 'tape']
const TYPE_SCALES = [0.94, 1, 1.06, 1.14]
const MOTIF_SIZES = [34, 40, 46, 52]

/**
 * A small deterministic hash. Not cryptographic — it only has to spread short
 * strings across the design space without clustering.
 */
function hash(seed: string): number {
  let h = 2166136261
  for (let i = 0; i < seed.length; i++) {
    h ^= seed.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

function pick<T>(list: T[], h: number, salt: number): T {
  const n = (h >>> salt) ^ Math.imul(h, salt + 7)
  return list[Math.abs(n) % list.length]!
}

export function cardArt(deck: string, index: number): CardArt {
  const h = hash(`${deck}#${index}`)
  return {
    palette: pick(PALETTES, h, 3),
    motif: pick(MOTIFS, h, 7),
    frame: pick(FRAMES, h, 11),
    typeScale: pick(TYPE_SCALES, h, 17),
    motifSize: pick(MOTIF_SIZES, h, 23),
    angle: 130 + ((h >>> 5) % 8) * 14,
  }
}

/** Distinct looks the generator can produce. Used by tests, not shown to users. */
export function designSpace(): number {
  return PALETTES.length * MOTIFS.length * FRAMES.length * TYPE_SCALES.length * MOTIF_SIZES.length * 8
}
