import { useCallback, useEffect, useMemo, useState } from 'react'
import { Card } from '@/components/ui'
import { Icon } from '@/design-system/Icon'
import { useI18n } from '@/i18n'
import { db } from '@/db/db'
import { DECKS, DECK_BY_ID, totalQuestions, type DeckId } from './deck'
import { dailyIndex, markSeen, nextIndex, remainingCount, resetDeck, type DrawState } from './draw'
import { CardFace } from './CardFace'
import './cards.css'

const STATE_KEY = 'cards.state'

/**
 * Kartu Berdua — the card game.
 *
 * Deliberately not a quiz and not scored: there is no right answer, nothing is
 * counted, and nobody wins. It is a prompt to talk, which is the only thing the
 * rest of the app is for too.
 */
export default function CardsScreen() {
  const { t } = useI18n()
  const [deck, setDeck] = useState<DeckId>('dalam')
  const [state, setState] = useState<DrawState>({ seen: {} })
  const [index, setIndex] = useState<number | null>(null)
  const [wrapped, setWrapped] = useState(false)
  const [loaded, setLoaded] = useState(false)

  // Progress lives in settings rather than a new store: it is a preference
  // ("which have we seen"), not a record of anything the couple wrote.
  useEffect(() => {
    void db.settings.get(STATE_KEY).then((row) => {
      if (row?.value) setState(row.value as DrawState)
      setLoaded(true)
    })
  }, [])

  const persist = useCallback((next: DrawState) => {
    setState(next)
    void db.settings.put({ key: STATE_KEY, value: next })
  }, [])

  const today = useMemo(() => dailyIndex(deck), [deck])
  const shown = index ?? today
  const question = DECK_BY_ID.get(deck)?.questions[shown] ?? ''
  const left = remainingCount(deck, state)

  function draw() {
    const { index: i, wrapped: w } = nextIndex(deck, state)
    setIndex(i)
    setWrapped(w)
    persist(w ? markSeen(resetDeck(state, deck), deck, i) : markSeen(state, deck, i))
  }

  function switchDeck(id: DeckId) {
    setDeck(id)
    setIndex(null)
    setWrapped(false)
  }

  return (
    <div className="stack">
      <h1>{t('cards.title')}</h1>
      <p className="card__hint">{t('cards.subtitle', { n: totalQuestions() })}</p>

      <div className="deckstage">
        <div className="deckstage__stack">
          <CardFace
            key={`${deck}-${shown}`}
            className="deckstage__card"
            deck={deck}
            index={shown}
            text={question}
            kicker={t(DECK_BY_ID.get(deck)?.name ?? 'cards.title')}
          />
        </div>

        {wrapped && (
          <p className="banner" role="status">
            <Icon name="info" size={18} />
            {t('cards.wrapped')}
          </p>
        )}

        <div className="deckstage__actions">
          <button type="button" className="btn" onClick={draw}>
            <Icon name="date" size={18} />
            {index === null ? t('cards.open') : t('cards.next')}
          </button>
          {index !== null && (
            <button type="button" className="btn btn--ghost" onClick={() => setIndex(null)}>
              <Icon name="chevron-left" size={18} />
              {t('cards.backToToday')}
            </button>
          )}
        </div>

        <p className="card__hint">
          {index === null ? t('cards.todayNote') : t('cards.left', { n: left })}
        </p>
      </div>

      <Card title={t('cards.pickDeck')} icon="heart" hint={t('cards.pickDeckHint')}>
        <div className="deckgrid" role="group" aria-label={t('cards.pickDeck')}>
          {DECKS.map((d) => (
            <button
              key={d.id}
              type="button"
              className="decktile"
              aria-pressed={deck === d.id}
              onClick={() => switchDeck(d.id)}
            >
              <strong>{t(d.name)}</strong>
              <small>{t(d.desc)}</small>
              <span className="decktile__count">
                {t('cards.deckCount', { n: d.questions.length })}
              </span>
            </button>
          ))}
        </div>
      </Card>

      {loaded && left === 0 && (
        <Card title={t('cards.resetTitle')} icon="repair" hint={t('cards.resetHint')}>
          <button type="button" className="btn btn--ghost btn--block" onClick={() => persist(resetDeck(state, deck))}>
            {t('cards.reset')}
          </button>
        </Card>
      )}
    </div>
  )
}
