/**
 * The little drawing at the top of every card.
 *
 * The first version of these cards was a question typed onto a gradient, and it
 * looked like a form field. Every reference deck worth copying — the pastel
 * affirmation packs, the kawaii sticker sheets — leads with a small drawing and
 * lets the words sit under it. That is what makes a card feel like a card
 * instead of a paragraph.
 *
 * Drawn here rather than imported: they inherit the card's own accent colour,
 * stay crisp at any size, and add nothing to download.
 */

export type MotifId =
  | 'sun' | 'cloud' | 'moon' | 'star' | 'heart' | 'flower' | 'rainbow'
  | 'plant' | 'cat' | 'bunny' | 'bee' | 'cup' | 'balloon' | 'butterfly'
  | 'wave' | 'sparkles'

export const MOTIFS: MotifId[] = [
  'sun', 'cloud', 'moon', 'star', 'heart', 'flower', 'rainbow',
  'plant', 'cat', 'bunny', 'bee', 'cup', 'balloon', 'butterfly',
  'wave', 'sparkles',
]

/** A face, reused so every creature smiles the same way. */
function Face({ x = 0, y = 0, blush = true }: { x?: number; y?: number; blush?: boolean }) {
  return (
    <g transform={`translate(${x} ${y})`}>
      <circle cx="-6" cy="-2" r="1.9" fill="currentColor" />
      <circle cx="6" cy="-2" r="1.9" fill="currentColor" />
      <path d="M-4 4c2.4 2.2 5.6 2.2 8 0" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" />
      {blush && (
        <>
          <ellipse cx="-11" cy="2.5" rx="3" ry="2" fill="currentColor" opacity="0.28" />
          <ellipse cx="11" cy="2.5" rx="3" ry="2" fill="currentColor" opacity="0.28" />
        </>
      )}
    </g>
  )
}

export function Motif({ id, tone }: { id: MotifId; tone: string }) {
  // `tone` fills the shape; `currentColor` (the card ink) draws the face, so
  // the expression is always readable whatever the fill is.
  const s = { fill: tone }
  switch (id) {
    case 'sun':
      return (
        <g>
          <circle cx="50" cy="50" r="22" {...s} />
          <g stroke={tone} strokeWidth="4" strokeLinecap="round">
            <path d="M50 18V8M50 92v-10M18 50H8M92 50h-10M27 27l-7-7M80 80l-7-7M73 27l7-7M20 80l7-7" />
          </g>
          <Face x={50} y={50} />
        </g>
      )
    case 'cloud':
      return (
        <g>
          <path d="M28 72a17 17 0 0 1 2-34 20 20 0 0 1 38 6 15 15 0 0 1-3 28Z" {...s} />
          <Face x={48} y={56} />
        </g>
      )
    case 'moon':
      return (
        <g>
          <path d="M62 16a36 36 0 1 0 22 64A30 30 0 0 1 62 16Z" {...s} />
          <Face x={52} y={52} blush={false} />
        </g>
      )
    case 'star':
      return (
        <g>
          <path d="M50 12l11 24 26 3-19 18 5 26-23-13-23 13 5-26-19-18 26-3Z" {...s} />
          <Face x={50} y={46} />
        </g>
      )
    case 'heart':
      return (
        <g>
          <path d="M50 86C24 66 12 54 12 38A19 19 0 0 1 50 30 19 19 0 0 1 88 38c0 16-12 28-38 48Z" {...s} />
          <Face x={50} y={44} />
        </g>
      )
    case 'flower':
      return (
        <g>
          {[0, 72, 144, 216, 288].map((a) => (
            <ellipse key={a} cx="50" cy="28" rx="11" ry="16" {...s} transform={`rotate(${a} 50 48)`} />
          ))}
          <circle cx="50" cy="48" r="12" fill="currentColor" opacity="0.16" />
          <Face x={50} y={48} />
        </g>
      )
    case 'rainbow':
      return (
        <g fill="none" strokeLinecap="round">
          <path d="M16 74a34 34 0 0 1 68 0" stroke={tone} strokeWidth="9" />
          <path d="M29 74a21 21 0 0 1 42 0" stroke={tone} strokeWidth="9" opacity="0.55" />
          <circle cx="18" cy="76" r="7" fill={tone} stroke="none" />
          <circle cx="82" cy="76" r="7" fill={tone} stroke="none" />
        </g>
      )
    case 'plant':
      return (
        <g>
          <path d="M34 58h32l-4 30a4 4 0 0 1-4 4H42a4 4 0 0 1-4-4Z" {...s} />
          <path d="M50 58V34" stroke={tone} strokeWidth="4" strokeLinecap="round" fill="none" />
          <ellipse cx="38" cy="34" rx="12" ry="8" {...s} transform="rotate(-24 38 34)" />
          <ellipse cx="62" cy="30" rx="12" ry="8" {...s} transform="rotate(22 62 30)" />
          <Face x={50} y={74} />
        </g>
      )
    case 'cat':
      return (
        <g>
          <path d="M24 42l-4-18 18 9a34 34 0 0 1 24 0l18-9-4 18a30 30 0 1 1-52 0Z" {...s} />
          <Face x={50} y={52} />
          <path d="M30 52h-9M30 58h-9M70 52h9M70 58h9" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" opacity="0.55" />
        </g>
      )
    case 'bunny':
      return (
        <g>
          <ellipse cx="38" cy="24" rx="7" ry="18" {...s} />
          <ellipse cx="62" cy="24" rx="7" ry="18" {...s} />
          <circle cx="50" cy="60" r="26" {...s} />
          <Face x={50} y={58} />
        </g>
      )
    case 'bee':
      return (
        <g>
          <ellipse cx="50" cy="56" rx="24" ry="19" {...s} />
          <path d="M42 39v34M56 40v32" stroke="currentColor" strokeWidth="4" opacity="0.3" />
          <ellipse cx="34" cy="34" rx="12" ry="8" fill="currentColor" opacity="0.22" transform="rotate(-28 34 34)" />
          <ellipse cx="66" cy="34" rx="12" ry="8" fill="currentColor" opacity="0.22" transform="rotate(28 66 34)" />
          <Face x={50} y={54} />
        </g>
      )
    case 'cup':
      return (
        <g>
          <path d="M26 44h44v22a20 20 0 0 1-20 20h-4a20 20 0 0 1-20-20Z" {...s} />
          <path d="M70 50h6a9 9 0 0 1 0 18h-6" fill="none" stroke={tone} strokeWidth="5" />
          <path d="M38 32c4-4 4-8 0-12M52 32c4-4 4-8 0-12M66 32c4-4 4-8 0-12" fill="none" stroke={tone} strokeWidth="3.4" strokeLinecap="round" opacity="0.7" />
          <Face x={48} y={64} />
        </g>
      )
    case 'balloon':
      return (
        <g>
          <ellipse cx="50" cy="42" rx="25" ry="29" {...s} />
          <path d="M50 71v20" stroke={tone} strokeWidth="3" strokeLinecap="round" fill="none" />
          <path d="M46 71h8l-4 6Z" {...s} />
          <Face x={50} y={42} />
        </g>
      )
    case 'butterfly':
      return (
        <g>
          <ellipse cx="30" cy="38" rx="17" ry="14" {...s} transform="rotate(-18 30 38)" />
          <ellipse cx="70" cy="38" rx="17" ry="14" {...s} transform="rotate(18 70 38)" />
          <ellipse cx="34" cy="64" rx="13" ry="11" {...s} opacity="0.75" />
          <ellipse cx="66" cy="64" rx="13" ry="11" {...s} opacity="0.75" />
          <rect x="47" y="32" width="6" height="38" rx="3" fill="currentColor" opacity="0.5" />
          <Face x={50} y={46} blush={false} />
        </g>
      )
    case 'wave':
      return (
        <g fill="none" stroke={tone} strokeWidth="7" strokeLinecap="round">
          <path d="M10 42q12-14 24 0t24 0 24 0" />
          <path d="M10 60q12-14 24 0t24 0 24 0" opacity="0.7" />
          <path d="M10 78q12-14 24 0t24 0 24 0" opacity="0.4" />
        </g>
      )
    case 'sparkles':
      return (
        <g {...s}>
          <path d="M50 14c3 18 10 25 28 28-18 3-25 10-28 28-3-18-10-25-28-28 18-3 25-10 28-28Z" />
          <path d="M22 62c1.6 9 5 12.6 14 14-9 1.6-12.4 5-14 14-1.6-9-5-12.4-14-14 9-1.6 12.4-5 14-14Z" opacity="0.6" />
          <path d="M78 12c1.2 7 3.8 9.6 10.6 10.8-6.8 1.2-9.4 3.8-10.6 10.6-1.2-6.8-3.8-9.4-10.6-10.6C74.2 21.6 76.8 19 78 12Z" opacity="0.45" />
        </g>
      )
  }
}
